<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetSelectedLanguage, GetLanguages } from '@wails/go/gui/App.js';
	import { installState } from '$lib/store.svelte';
	import ConfirmDialog from '$components/ConfirmDialog.svelte';
	import type { LanguageOption } from '$lib/types';
	import { TYPE_ESP, TYPE_SYSTEM } from '$lib/types';
	import { t } from '$lib/i18n';
	import { glyph, STEP_ICONS } from '$lib/icons';
	import { groupDigits } from '$lib/format';
	import PageLayout from '$components/PageLayout.svelte';

	const pageIcon = glyph(STEP_ICONS.confirmation);

	let languages = $state<LanguageOption[]>([]);
	let selectedLanguageName = $state<string>('—');

	async function loadLanguageInfo(): Promise<void> {
		try {
			languages = await GetLanguages();
			const code = await GetSelectedLanguage();
			const lang = languages.find((l) => l.code === code);
			selectedLanguageName = lang?.name || code || '—';
		} catch {
			selectedLanguageName = '—';
		}
	}

	loadLanguageInfo();

	// Whether the manual layout has at least one designated (ESP or System) row.
	const hasDesignated = $derived.by(
		() => !!installState.manualLayout?.partitions?.some((p) => p.type === TYPE_ESP || p.type === TYPE_SYSTEM),
	);

	// References to measure against, so the partition table scrolls internally
	// (not the page) only when it's taller than the room available.
	let pageContentEl = $state<HTMLElement | null>(null);
	let planScrollEl = $state<HTMLElement | null>(null);

	// Bound .plan-scroll's height to the space left over in the column after the
	// fixed summary content (language, user, disk header). When the table fits,
	// the summary stays naturally sized and vertically centered; when it doesn't
	// (many partitions), the table fills the column and scrolls internally.
	function updatePlanScrollHeight(): void {
		if (!pageContentEl || !planScrollEl) return;
		const summary = pageContentEl.querySelector<HTMLElement>('.summary');
		if (!summary) return;
		const available = pageContentEl.clientHeight;
		// summary's natural height includes the table's current height; subtracting
		// it leaves the height of everything else, which is stable either way.
		const fixed = summary.clientHeight - planScrollEl.offsetHeight;
		planScrollEl.style.maxHeight = Math.max(0, available - fixed) + 'px';
	}

	$effect(() => {
		// Re-measure whenever the partition list changes (add/remove rows).
		// Track the length explicitly: rows are mutated in place, so reading the
		// array object alone would not subscribe to push/splice.
		const partitionCount = installState.manualLayout?.partitions?.length ?? 0;
		void partitionCount;
		updatePlanScrollHeight();
		window.addEventListener('resize', updatePlanScrollHeight);
		return () => window.removeEventListener('resize', updatePlanScrollHeight);
	});
</script>

<PageLayout
	icon={pageIcon}
	title={t('page.confirmation.title')}
	subtitle={t('page.confirmation.subtitle')}
	variant="summary"
	bind:contentEl={pageContentEl}
>
	<div class="summary">
		<div class="summary-section">
			<h3 class="section-title">{t('page.confirmation.sectionLanguage')}</h3>
			<p class="section-value">{selectedLanguageName}</p>
		</div>

		<div class="summary-section">
			<h3 class="section-title">{t('page.confirmation.sectionUser')}</h3>
			<p class="section-value">
				{t('page.confirmation.username')}: <strong>{installState.username || '—'}</strong>
			</p>
			{#if installState.password}
				<p class="section-value">
					{t('page.confirmation.password')}: <strong>{'●'.repeat(installState.password.length)}</strong>
				</p>
			{/if}
		</div>

		<div class="summary-section">
			<h3 class="section-title">{t('page.confirmation.sectionDisk')}</h3>
			{#if installState.disk}
				<div class="disk-summary">
					<p class="section-value disk-name">
						{installState.disk.model || '—'} ({installState.disk.sizeFormatted} {t(installState.disk.rotational ? 'disk.hdd' : 'disk.ssd')} {installState.disk.trans?.toUpperCase() || ''})
					</p>
					{#if installState.disk.serial}
						<p class="disk-extra">{t('validation.serial')}: <span class="tag serial-tag">{installState.disk.serial}</span></p>
					{/if}
					<!-- Path + current fs are redundant in manual mode: the plan table lists every path, and a disk has no single filesystem. -->
					{#if !installState.manualMode}
						<p class="disk-path">{t('page.installation.target')}: <code>{installState.disk.path}</code></p>
					{/if}

					{#if installState.manualMode}
						<!-- Manual mode: show the partition plan the user designed -->
						{#if installState.manualLayout && hasDesignated}
							<div class="plan-scroll" bind:this={planScrollEl}>
								<table class="plan-table">
								<thead>
									<tr>
										<th scope="col" class="plan-col-name">{t('page.confirmation.colName')}</th>
										<th scope="col" class="plan-col-size">{t('page.confirmation.colSize')}</th>
										<th scope="col" class="plan-col-role">{t('page.confirmation.colRole')}</th>
									</tr>
								</thead>
								<tbody>
									{#each installState.manualLayout.partitions ?? [] as part (part.index)}
										<tr class:designated={part.type === TYPE_ESP || part.type === TYPE_SYSTEM}>
											<td class="plan-col-name">
												{#if part.path}
													{part.path}
												{:else}
													<span class="part-new">{t('manual.newPart')}</span>
												{/if}
											</td>
											<td class="plan-col-size">{groupDigits(part.sizeMB)}</td>
											<td class="plan-col-role">
												<span class="tag role-tag {part.type}">{t('manual.type.' + (part.type || 'preserve'))}</span>
											</td>
										</tr>
									{/each}
								</tbody>
							</table>
							</div>
						{:else}
							<p class="disk-extra">{t('manual.dualbootHint')}</p>
						{/if}
					{:else}
						<p class="disk-extra">
							{t('page.diskSelection.selectedFileSystem')}: <span class="tag fs-tag">{installState.fileSystem || '—'}</span>
						</p>
					{/if}

					{#if installState.luksEnabled}
						<div class="option-row">
							<span class="tag luks-tag">{t('page.confirmation.luksEncrypted')}</span>
							<span class="option-hint">{t('disk.encryptHint')}</span>
						</div>
					{/if}
					{#if installState.lvmEnabled}
						<div class="option-row">
							<span class="tag lvm-tag">{t('page.confirmation.lvmEnabled')}</span>
							<span class="option-hint">{t('disk.lvmHint')}</span>
						</div>
					{/if}
				</div>
			{:else}
				<p class="section-value error">{t('validation.noDiskSelected')}</p>
			{/if}
		</div>
	</div>
</PageLayout>

	<!-- Installation confirmation (mode-aware copy: wipe vs. dualboot-safe) -->
	<ConfirmDialog bind:show={installState.showConfirmDialog} />

<style>
	.summary {
		display: flex;
		flex-direction: column;
		gap: var(--spacing-md);
		width: 100%;
	}

	.summary-section {
		display: flex;
		flex-direction: column;
		gap: var(--spacing-xs);
	}

	.section-title {
		font-size: var(--font-size-sm);
		font-weight: 600;
		text-transform: uppercase;
		letter-spacing: 0.05em;
		color: var(--color-text-muted);
		margin: 0;
	}

	.section-value {
		margin: 0;
		font-size: var(--font-size-md);
	}

	.disk-summary {
		display: flex;
		flex-direction: column;
		gap: var(--spacing-xs);
		width: 100%;
	}

	.disk-name {
		margin-bottom: var(--spacing-sm);
		font-size: var(--font-size-md);
	}

	.disk-path {
		margin: 0;
		font-size: var(--font-size-sm);
		color: var(--color-text-muted);
	}

	.disk-path code {
		background-color: var(--color-bg-light);
		padding: 2px 6px;
		border-radius: var(--radius-sm);
		font-family: var(--font-mono);
		font-size: var(--font-size-sm);
	}

	.disk-extra {
		margin: 0;
		font-size: var(--font-size-sm);
		color: var(--color-text-muted);
	}

	.error {
		color: var(--color-danger);
	}

	/* Manual partition plan — native table keeps every column perfectly aligned */
	/* Scroll wrapper: scrolls internally when the table is taller (many
		partitions) or wider (narrow window) than its space. Its max-height is
		set by JS so it fills the remaining column only when needed, keeping the
		summary centered whenever it fits. */
	.plan-scroll {
		width: 100%;
		overflow: auto;
	}

	.plan-table {
		border-spacing: 0;
		width: 100%;
		/* Fill the column on normal screens, but grow to its content (and force
		the wrapper to scroll) when the column is too narrow. */
		min-width: max-content;
		border: 1.5px solid var(--color-border-light);
		border-radius: var(--radius-lg);
		background: var(--color-bg-white);
		font-size: var(--font-size-sm);
	}

	.plan-table thead tr {
		border-bottom: 1px solid var(--color-border-light);
	}

	.plan-table tbody tr {
		border-bottom: 1px solid var(--color-border-subtle);
	}

	.plan-table tbody tr:last-child {
		border-bottom: none;
	}

	.plan-table tbody tr.designated {
		background: var(--color-primary-lighter);
	}

	.plan-table th,
	.plan-table td {
		padding: var(--spacing-xs) var(--spacing-md);
		font-family: var(--font-mono);
		font-variant-numeric: tabular-nums;
		text-align: left;
		vertical-align: middle;
		margin: 0;
	}

	.plan-table th {
		font-size: 0.68rem;
		font-weight: 600;
		text-transform: uppercase;
		letter-spacing: 0.04em;
		color: var(--color-text-muted);
	}

	.plan-col-name {
		font-weight: 600;
		color: var(--color-text);
		min-width: 0;
	}

	.plan-col-size {
		text-align: right;
		white-space: nowrap;
	}

	.plan-col-role {
		white-space: nowrap;
	}

		.part-new {
		font-size: 0.72rem;
		color: var(--color-progress);
		font-weight: 600;
	}

	.tag {
		display: inline-block;
		padding: 1px 8px;
		border-radius: var(--radius-pill);
		background: var(--color-bg-light);
		color: var(--color-text);
		font-family: var(--font-sans);
		font-size: 0.75rem;
		font-weight: 600;
	}

	.option-row {
		display: flex;
		align-items: flex-start;
		flex-wrap: wrap;
		gap: var(--spacing-xs) var(--spacing-sm);
	}

	.option-hint {
		font-size: var(--font-size-sm);
		color: var(--color-text-muted);
		line-height: 1.45;
	}

	.luks-tag {
		background: var(--color-danger-bg);
		color: var(--color-danger);
	}

	.lvm-tag {
		background: var(--color-primary-lighter);
		color: var(--color-primary);
	}

	.role-tag.esp {
		background: var(--color-primary-lighter);
		color: var(--color-primary);
	}

	.role-tag.system {
		background: var(--color-progress);
		color: var(--color-on-primary);
	}
</style>
